import { FilterConfig } from '../types';

const GLOBAL_COUNTRY = 'ABI';
const GLOBAL_WEIGHT_TYPE = 'bu';
const COUNTRY_WEIGHT_TYPE = 'ind';

export const isWeightTypeDisabledForCountry = (country: unknown): boolean =>
  country != null && country !== '' && country !== GLOBAL_COUNTRY;

const getWeightTypeDefault = (
  filterData: Parameters<NonNullable<FilterConfig['calculator']>>[0],
  country: unknown,
) => {
  const desiredValue =
    country == null || country === '' || country === GLOBAL_COUNTRY
      ? GLOBAL_WEIGHT_TYPE
      : COUNTRY_WEIGHT_TYPE;
  const options = filterData.weight_type?.values ?? [];

  return (
    options.find((option) => option.value === desiredValue)?.value ??
    filterData.weight_type?.default?.value ??
    options[0]?.value ??
    null
  );
};

export const weightTypeFilterConfig: FilterConfig = {
  key: 'weight_type',
  order: 58,
  isCommon: false,
  parentKey: 'country',
  calculator: (filterData, currentDefaults) =>
    getWeightTypeDefault(filterData, currentDefaults.country),
  dependentDefaultCascadingCalculator: (filterData, currentValues) =>
    getWeightTypeDefault(filterData, currentValues.country),
  validator: (filterData, value, currentApplied) => {
    if (isWeightTypeDisabledForCountry(currentApplied?.country)) return false;
    if (value == null || value === '') return true;

    return (
      filterData.weight_type?.values?.some(
        (option) => option.value === value,
      ) ?? false
    );
  },
  dependencies: [],
  metadata: {
    displayName: 'Weight Type',
    description: 'Market Share weight type',
  },
};
